sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float zoom;
uniform float sizing;
uniform float offset;
uniform float mirror;
uniform float vertical;
uniform float angle;
half4 main(float2 coord) {
    float2 c = size * 0.5;
    float a = radians(angle);
    float cs = cos(a);
    float sn = sin(a);
    float2 p = coord - c;
    p = float2(cs * p.x + sn * p.y, -sn * p.x + cs * p.y);
    if (sizing > 0.5) p /= max(zoom, 0.005);
    else p *= max(zoom, 0.005);
    float2 g = p / max(size, float2(1.0)) + 0.5;
    if (vertical > 0.5) g.y -= offset * floor(g.x);
    else g.x -= offset * floor(g.y);
    float2 n = floor(g);
    float2 t = g - n;
    if (mirror > 0.5) t = mix(t, 1.0 - t, mod(n, 2.0));
    return image.eval(clamp(t * size, float2(0.5), size - 0.5));
}
